import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colorInk = new Color('#16161d');
  const colorPaper = new Color('#e8ecf2');
  const colorAccent = new Color('#ff2a38');
  const colorSurface = new Color('#0b0b10');

  // 1. STAGE BACKDROP (Dark first design, gradient, prevents flat void)
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.85 });

  // Custom TSL for vertical gradient with grain styling
  const customUV = uv();
  const gradientNode = customUV.y.mix(colorSurface, colorInk);
  backdropMat.colorNode = gradientNode;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -0.4);
  group.add(backdropMesh);

  // 2. SPRITE CARD WITH CERAMIC GRAIN
  // Sized to atlas region aspect ratio (512x320 -> 1.6 aspect)
  const width = 2.4;
  const height = width / 1.6;
  const cardGeo = new PlaneGeometry(width, height);

  // Setup texture coordinates based on Atlas Region: 0, 0, 512, 320
  // Assuming a standard 512x512 atlas layout
  const uRange = vec2(0.0, 1.0);
  const vRange = vec2(0.375, 1.0); // 320/512 = 0.625. Top-left origin: [0, 1 - 0.625] -> [0, 0.375]

  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  const timeline = gsap.timeline();

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      // Crop texture node via TSL mapping
      const mappedUV = uv().mul(vRange.y.sub(vRange.x)).add(vec2(0.0, vRange.x));
      cardMat.colorNode = texture(tex, mappedUV).mul(colorPaper);
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture", err);
      cardMat.colorNode = colorSurface;
    });
  } else {
    cardMat.colorNode = colorSurface;
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // 3. TEXT CONTENT
  // Extract "Pricing 2" headline
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStr = items[0]?.text ?? "Pricing 2";

  const textElement = ctx.fontAtlas.createText(textStr, {
    fontSize: 22,
    color: '#16161d', // Dark ink text on light paper ceramic grain card
    align: 'center'
  });

  // Position slightly forward to avoid z-fighting
  textElement.position.set(0, 0, 0.02);
  group.add(textElement);

  // 4. ANIMATION - Soft intro reveal
  group.position.y += 0.15;
  group.scale.set(0.95, 0.95, 0.95);

  timeline.to(group.position, {
    y: 0,
    duration: 0.8,
    ease: 'power3.out'
  });

  timeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.8,
    ease: 'back.out(1.2)'
  }, 0);

  // Clean up resources and GSAP timelines
  group.userData.cleanup = () => {
    timeline.kill();
    cardGeo.dispose();
    cardMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
  };

  return group;
}
